/* BISM4RCK-KUN3H0 2026 */ include app_path('views/layouts/header.php'); ?><div class="container-fluid"><div class="d-flex justify-content-between align-items-center mb-3"><h2>Gate Logs</h2></div><div class="gh-card p-4 mb-3"><form class="row g-2" method="get"><div class="col-md-3"><select class="form-select" name="event_type"><option value="">All events</option><?php foreach(['rfid_scan','qr_scan','barcode_scan','walk_in_checkin','manual_open'] as $e): ?><option value="<?=e($e)?>" <?=$filters['event_type']===$e?'selected':''?>><?=e(ucwords(str_replace('_',' ',$e)))?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="gate_status"><option value="">All status</option><?php foreach(['approved','denied','pending','manual_override'] as $s): ?><option value="<?=e($s)?>" <?=$filters['gate_status']===$s?'selected':''?>><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="actor_user_id"><option value="">All operators</option><?php foreach($actors as $a): ?><option value="<?=e($a['id'])?>" <?=$filters['actor_user_id']==(string)$a['id']?'selected':''?>><?=e(strtoupper($a['role']).' — '.$a['full_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><input class="form-control" name="search" value="<?=e($filters['search'])?>" placeholder="Plate, RFID, notes"></div><div class="col-md-1"><button class="btn gh-primary w-100">Go</button></div></form></div><div class="gh-card p-4"><div class="table-responsive"><table class="table gh-table align-middle"><thead><tr><th>Time</th><th>Event</th><th>Operator</th><th>Plate</th><th>RFID</th><th>Visitor</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td><?=e($log['created_at'])?></td><td><?=e($log['event_type'])?></td><td><?=e(($log['actor_name']?:'System').' '.($log['actor_role']?'('.$log['actor_role'].')':''))?></td><td><?=e($log['plate_number']?:'—')?></td><td><?=e($log['rfid_uid']?:'—')?></td><td><?=e($log['walk_in_id']?'WALK-IN #'.$log['walk_in_id']:($log['visitor_request_id']?'REQUEST #'.$log['visitor_request_id']:'—'))?></td><td><span class="badge rounded-pill <?=e(gate_badge($log['gate_status']))?>"><?=e($log['gate_status'])?></span></td><td><?=e($log['log_notes'])?></td></tr><?php endforeach;?><?php if(empty($logs)): ?><tr><td colspan="8" class="text-center text-muted py-4">No gate logs match.</td></tr><?php endif;?></tbody></table></div></div></div><?php include app_path('views/layouts/footer.php'); ?>
